def maximize_profit(*coeffs: float) -> int:
    """
    Find the number of products x that the factory should produce each month to maximize the total profit.

    Args:
    coeffs: Coefficients of the cost and price functions.
        coeffs[0]: Constant term in the cost function.
        coeffs[1]: Linear term coefficient in the cost function.
        coeffs[2]: Quadratic term coefficient in the cost function.
        coeffs[3]: Cubic term coefficient in the cost function.
        coeffs[4]: Constant term in the price function.
        coeffs[5]: Linear term coefficient in the price function.

    Returns:
        The number of products x that the factory should produce each month to maximize the total profit.
    """

    # Define the cost and price functions
    def cost(x: float) -> float:
        return coeffs[0] + coeffs[1] * x - coeffs[2] * x**2 + coeffs[3] * x**3

    def price(x: float) -> float:
        return coeffs[4] - coeffs[5] * x

    # Define the profit function
    def profit(x: float) -> float:
        return price(x) * x - cost(x)

    # Find the derivative of the profit function
    def profit_derivative(x: float) -> float:
        return price(x) + x * (price_derivative(x)) - (cost_derivative(x))

    # Find the second derivative of the profit function
    def profit_second_derivative(x: float) -> float:
        return price_derivative(x) + x * (price_second_derivative(x)) - (cost_second_derivative(x))

    # Define the derivatives of the cost and price functions
    def cost_derivative(x: float) -> float:
        return coeffs[1] - 2 * coeffs[2] * x + 3 * coeffs[3] * x**2

    def price_derivative(x: float) -> float:
        return -coeffs[5]

    def cost_second_derivative(x: float) -> float:
        return -2 * coeffs[2] + 6 * coeffs[3] * x

    def price_second_derivative(x: float) -> float:
        return 0

    # Use the Newton-Raphson method to find the maximum of the profit function
    x = 100  # Initial guess
    while True:
        # Calculate the next estimate of the maximum
        x_next = x - profit_derivative(x) / profit_second_derivative(x)

        # Check for convergence
        if abs(x_next - x) < 1e-6:
            break

        # Update the estimate
        x = x_next

    # Return the number of products as an integer
    return round(x)
