import math

def calculate_probability_score(num_questions: int, num_options: int, correct_points: int, incorrect_points: int, target_score: int) -> float:
    if target_score < 0 or target_score > num_questions * correct_points:
        return 0.0

    total_points = num_questions * correct_points
    probability = 0.0

    for score in range(target_score, total_points + 1):
        combinations = math.comb(num_questions, score - target_score)
        for i in range(num_questions):
            if score - target_score == i:
                combinations *= num_options - 2
            else:
                combinations *= num_options - 1
        probability += combinations * (correct_points / num_options) ** (score - target_score) * (incorrect_points / num_options) ** (num_questions - score + target_score)

    return round(100 * probability, 2)

