def count_ap_triplets(n: int, limit: int) -> int:
    """
    Counts the number of ways to choose 3 distinct cards from a box of n cards
    such that their numbers form an arithmetic progression and their sum does not exceed limit.

    Args:
        n (int): The total number of cards in the box.
        limit (int): The maximum sum of the three card numbers.

    Returns:
        int: The number of ways to choose 3 cards satisfying the conditions.
    """
    count = 0
    for i in range(1, n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # Check if the numbers form an arithmetic progression
                if (j - i) == (k - j):
                    # Check if the sum does not exceed the limit
                    if i + j + k <= limit:
                        count += 1
    return count

