def solve_min_distance(mx: float, my: float) -> float:
    """
    Calculate the minimum distance between a point (mx, my) and the curve g(x) = (x + 1)/(x - 2) for x > 2.

    Args:
    mx (float): The x-coordinate of the point.
    my (float): The y-coordinate of the point.

    Returns:
    float: The minimum distance between the point and the curve, in meters, rounded to two decimal places.
    """

    # Define the function g(x) = (x + 1)/(x - 2) for x > 2
    def g(x: float) -> float:
        return (x + 1) / (x - 2)

    # Define the function for the derivative of g(x)
    def g_prime(x: float) -> float:
        return (x - 2) / ((x - 2)**2)

    # Define the function for the distance between a point (x, y) and the curve g(x)
    def distance(x: float, y: float) -> float:
        return np.abs(y - g(x))

    # Define the function for the derivative of the distance
    def distance_prime(x: float, y: float) -> float:
        return np.sign(y - g(x)) * (1 - g_prime(x) * (x - 2)) / ((x - 2)**2)

    # Initialize the minimum distance and the corresponding x-value
    min_distance = float('inf')
    x_min = mx

    # Perform a binary search to find the minimum distance
