def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = math.isqrt(n)
    for i in range(3, sqrt_n + 1, 2):
        if n % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    """Calculate the probability of at least 2 prime numbers and an even sum."""
    prime_numbers = [i for i in range(1, total_tickets + 1) if is_prime(i)]
    non_prime_numbers = [i for i in range(1, total_tickets + 1) if not is_prime(i)]

    total_ways = math.comb(total_tickets, chosen_tickets)

    prime_ways = 0
    for i in range(len(prime_numbers)):
        for j in range(i + 1, len(prime_numbers)):
            for k in range(j + 1, len(prime_numbers)):
                for last in range(k + 1, len(prime_numbers)):
                    if sum([prime_numbers[i], prime_numbers[j], prime_numbers[k], prime_numbers[last]]) % 2 == 0:
                        prime_ways += math.comb(len(prime_numbers), 4)

    non_prime_ways = 0
    for i in range(len(non_prime_numbers)):
